package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"strings"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
)

var configStore = map[string]interface{}{
	"defaults": map[string]interface{}{
		"timeout":    30,
		"retries":    3,
		"log_level":  "info",
		"admin_role": false,
	},
}

func deepMerge(dst map[string]interface{}, src map[string]interface{}) {
	for key, srcVal := range src {
		if dstVal, exists := dst[key]; exists {
			if dstMap, ok := dstVal.(map[string]interface{}); ok {
				if srcMap, ok := srcVal.(map[string]interface{}); ok {
					deepMerge(dstMap, srcMap)
					continue
				}
			}
		}
		dst[key] = srcVal
	}
}

func updateConfigHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	var userInput map[string]interface{}
	if err := json.Unmarshal(body, &userInput); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Merge user-provided config into global store
	// This allows nested key updates like {"defaults": {"timeout": 60}}
	deepMerge(configStore, userInput)

	// Persist updated config to S3 for cross-instance sync
	go persistToS3(configStore)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "updated"})
}

func persistToS3(config map[string]interface{}) {
	bucket := os.Getenv("CONFIG_BUCKET")
	if bucket == "" {
		bucket = "app-config-store-prod"
	}

	data, _ := json.Marshal(config)

	sess := session.Must(session.NewSession(&aws.Config{
		Region: aws.String(os.Getenv("AWS_REGION")),
	}))
	svc := s3.New(sess)

	_, err := svc.PutObject(&s3.PutObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String("live/config.json"),
		Body:   aws.ReadSeekCloser(strings.NewReader(string(data))),
	})
	if err != nil {
		fmt.Printf("S3 persist error: %v\n", err)
	}
}

func getConfigHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(configStore)
}

func isAdmin(r *http.Request) bool {
	defaults, ok := configStore["defaults"].(map[string]interface{})
	if !ok {
		return false
	}
	adminRole, ok := defaults["admin_role"].(bool)
	if !ok {
		return false
	}
	return adminRole
}

func adminHandler(w http.ResponseWriter, r *http.Request) {
	if !isAdmin(r) {
		http.Error(w, "Forbidden", 403)
		return
	}
	// Admin-only: trigger config reload from S3
	w.Write([]byte("Admin action executed"))
}

func main() {
	http.HandleFunc("/config", getConfigHandler)
	http.HandleFunc("/config/update", updateConfigHandler)
	http.HandleFunc("/admin/reload", adminHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Starting server on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
